#!/usr/bin/env node
import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
const ROOT=process.cwd(); const read=p=>JSON.parse(readFileSync(resolve(ROOT,p),'utf8'))
const stable=v=>Array.isArray(v)?`[${v.map(stable).join(',')}]`:v&&typeof v==='object'?`{${Object.keys(v).sort().map(k=>`${JSON.stringify(k)}:${stable(v[k])}`).join(',')}}`:JSON.stringify(v)
const sha=v=>`sha256:${createHash('sha256').update(stable(v)).digest('hex')}`
const input=read('reports/genesis-p5-candidate-inputs.json'); const manifest=read('data/lexicon/candidates/genesis-p5/manifest.json')
const candidates=manifest.shards.flatMap(meta=>read(meta.path).candidates); const byStrong=new Map(candidates.map(c=>[c.sourceStrong,c]))
const records=input.units.map(unit=>{const c=byStrong.get(unit.sourceStrong); assert.ok(c,`${unit.sourceStrong}: candidate missing`); assert.deepEqual(c.nodes.map(n=>n.sourceNodeId),unit.source.nodes.map(n=>n.sourceNodeId)); return {auditId:`AUDIT-${c.candidateId}`,baseStrong:c.baseStrong,sourceStrong:c.sourceStrong,group:unit.group,risk:c.risk,identity:c.identity,parserOutputFingerprint:unit.source.parserOutputFingerprint,candidateFingerprint:c.candidateFingerprint,pairs:unit.source.nodes.map((src,i)=>({sourceNodeId:src.sourceNodeId,parentId:src.parentId,depth:src.depth,order:src.order,sourceText:src.sourceText,sourceLocator:src.sourceLocator,textKo:c.nodes[i].textKo,confidence:c.nodes[i].confidence,riskFlags:c.nodes[i].riskFlags})),auditContract:{auditorRole:'claude-independent-auditor',allowedVerdicts:['PASS','REVISE','DISPUTE'],mustCheck:['source-fidelity','sense-boundary','korean-naturalness','theological-overreach','etymology-certainty','risk-routing'],sourceMutationAllowed:false,candidateMutationAllowed:false,approvalRegistryWriteAllowed:false,productionWriteAllowed:false}}})
const out={schemaVersion:1,bundleId:'genesis-p5-claude-audit-bundle-v1',book:'GEN',sourceInputBundleFingerprint:input.bundleFingerprint,candidateManifestFingerprint:manifest.bundleFingerprint,goldenControlExcluded:'H776',candidateGenerator:'GPT-5.6 Sol',requiredAuditor:'Claude independent audit',counts:{baseItems:24,candidateUnits:27,nodePairs:records.reduce((s,r)=>s+r.pairs.length,0),riskTiers:manifest.counts.riskTiers},routing:{R0:'Claude batch audit',R1:'Claude batch audit',R2:'Claude full audit',R3:'Claude full audit then Gemini dispute review',R4:'Claude full audit then human final wording Gate'},governance:{auditOnly:true,approvalRegistryWriteAllowed:false,serviceUiWriteAllowed:false,productionWriteAllowed:false,existingApprovedMeaningMutationAllowed:false},records}
assert.equal(out.counts.nodePairs,150); assert.equal(records.some(r=>r.baseStrong==='H776'||r.sourceStrong==='H776'),false)
out.bundleFingerprint=sha(out)
const target=resolve(ROOT,process.argv.find(a=>a.startsWith('--out='))?.slice(6)||'reports/genesis-p5-claude-audit-bundle.json'); mkdirSync(dirname(target),{recursive:true}); writeFileSync(target,`${JSON.stringify(out,null,2)}\n`); console.log(`✓ Claude audit bundle · units=27 · nodePairs=150 · R3=5 · R4=5`)
